:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  color: #183a38;
  background: #e8f1ef;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(ellipse at 15% 15%, #c3e3da, transparent 60%),
    radial-gradient(ellipse at 90% 85%, #d4dcef, transparent 60%),
    #e8f1ef;
}

.counter {
  width: min(100%, 440px);
  padding: clamp(24px, 6vw, 44px);
  border: 1px solid #ffffff;
  border-radius: 28px;
  background: rgba(255, 255, 255, .8);
  backdrop-filter: blur(18px);
  box-shadow: 0 20px 60px rgba(24, 58, 56, .1);
  text-align: center;
}

.eyebrow {
  margin: 0 0 16px;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
}

h1 { margin: 0; font-size: clamp(1.6rem, 5vw, 2rem); }
.description, .hint { color: #49615f; line-height: 1.6; }
.description { margin: 12px 0 28px; }
.readout { padding: 20px 0 30px; }
#count-label { display: block; font-size: .875rem; }
#count {
  display: block;
  margin-top: 8px;
  font-size: clamp(3rem, 15vw, 5rem);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.controls { display: flex; flex-wrap: wrap; gap: 12px; }
button {
  flex: 1 1 120px;
  min-height: 48px;
  border: 1px solid #245c53;
  border-radius: 14px;
  padding: 12px 18px;
  background: #245c53;
  color: #fff;
  font: inherit;
  font-weight: 650;
  cursor: pointer;
  transition: background-color 140ms ease, transform 140ms ease;
}
button:hover { background: #19473f; }
button:active { transform: translateY(1px); }
button.secondary { background: #f4f8f7; color: #245c53; }
button.secondary:hover { background: #e2eeea; }
button:focus-visible { outline: 3px solid #6048a0; outline-offset: 4px; }
.hint { margin: 24px 0 0; font-size: .8rem; }

@media (prefers-reduced-motion: reduce) {
  button { transition: none; }
  button:active { transform: none; }
}

'use strict';

const countOutput = document.getElementById('count');
const incrementButton = document.getElementById('increment');
const resetButton = document.getElementById('reset');
let count = 0n;

function renderCount() {
  countOutput.textContent = count.toString();
}

incrementButton.addEventListener('click', () => {
  count += 1n;
  renderCount();
});

resetButton.addEventListener('click', () => {
  count = 0n;
  renderCount();
});
